<?php
$latest=$wid?rows('SELECT r.position FROM keyword_rankings r JOIN keywords k ON k.id=r.keyword_id WHERE k.website_id=? AND r.date=(SELECT MAX(r2.date) FROM keyword_rankings r2 WHERE r2.keyword_id=k.id)',[$wid]):[];$top3=0;$top10=0;foreach($latest as $r){if($r['position']!==null && $r['position']<=3)$top3++;if($r['position']!==null && $r['position']<=10)$top10++;}
$categories=$audit?rows('SELECT category,COUNT(*) AS count FROM seo_issues WHERE audit_id=? AND status="open" GROUP BY category',[$audit['id']]):[];$severity=$audit?rows('SELECT severity,COUNT(*) AS count FROM seo_issues WHERE audit_id=? AND status="open" GROUP BY severity',[$audit['id']]):[];$severity=array_column($severity,'count','severity');
?><div class="grid grid-4 stack"><?php foreach(['Top 3 keywords'=>$latest?$top3:'—','Top 10 keywords'=>$latest?$top10:'—','Critical errors'=>$audit?($severity['critical']??0):'—','SEO opportunities'=>$audit?($severity['opportunity']??0):'—'] as $label=>$value):?><div class="card metric"><span class="metric-label"><?=e($label)?></span><div class="metric-value"><?=e($value)?></div></div><?php endforeach;?></div><div class="grid grid-2 stack"><div class="card"><h3>Issues by category</h3><?php Chart::bars(array_column($categories,'count','category'),'Open issues by category');?></div><div class="card"><h3>Keyword distribution</h3><?php Chart::bars($latest?['Top 3'=>$top3,'Positions 4–10'=>$top10-$top3,'Beyond top 10'=>count(array_filter($latest,fn($r)=>$r['position']>10))]:[],'Latest recorded keyword distribution');?><p class="small">Uses each keyword’s latest stored position. Organic traffic and backlink authority scores require verified provider data and are not estimated.</p></div></div>
